all_tasks=[]
for prefix,fmt,specs in [('RS','SYNOP',S),('RM','METAR',M),('RT','TAF',T)]:
 for n,(rid,cap,question,reference,why) in enumerate(specs,1):
  row=rows[rid]; assert row['format']==fmt
  task_id=f'{prefix}{n:02d}'
  prompt=('Decode the following user-provided '+fmt+' report for a controlled quality-assurance exercise. '
   'Return only one JSON object with exactly the requested keys, using JSON numbers, booleans, strings and null as appropriate. '
   'For SYNOP, sections change at 333; temperatures are degrees C and section 3 58/59 pressure changes and 7-group rainfall use tenths. '
   'Do not invent missing values or claim independent verification of the station observation.\n\n'+row['raw']+'\n\n'+question)
  all_tasks.append({'id':task_id,'format':fmt,'record_id':rid,'report_sha256':row['sha256'],'capability':cap,'model_visible_prompt':prompt,'reference':reference,'derivation':why})
assert len(all_tasks)==24 and len({x['record_id'] for x in all_tasks})==24
(D/'tasks.json').write_text(json.dumps(all_tasks,indent=2,ensure_ascii=False)+'\n')
manifest={name:hashlib.sha256((D/name).read_bytes()).hexdigest() for name in ('tasks.json','grader.py','create_tasks.py')}
(D/'freeze.json').write_text(json.dumps({'status':'pre-inference candidate freeze; no model trials','dataset_sha256':hashlib.sha256((P/'raw/attributed_reports.jsonl').read_bytes()).hexdigest(),'sha256':manifest},indent=2)+'\n')
print('24 tasks, 24 distinct report IDs,',sum(len(x['reference']) for x in all_tasks),'reference fields')
